TLM.f("Sancti/07-18",{"officium":"S. Camilli de Lellis Confessoris","rule":["vide C5","Gloria"],"fallback":"Commune/C5","from":{"GradualeP":"Commune/C5","Tractus":"Commune/C5"},"sections":{"Introitus":[{"k":"ref","la":"Joann 15:13"},{"k":"text","la":"Majórem hac dilectiónem nemo habet, ut ánimam suam ponat quis pro amícis suis."},{"k":"ref","la":"Ps 40:2"},{"k":"text","la":"Beátus, qui intéllegit super egénum et páuperem: in dic mala liberábit eum Dóminus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Majórem hac dilectiónem nemo habet, ut ánimam suam ponat quis pro amícis suis."}],"Oratio":[{"k":"text","la":"Deus, qui sanctum Camíllum, ad animárum in extrémo agóne luctántium subsídium, singulári caritátis prærogatíva decorásti: ejus, quǽsumus, méritis, spíritum nobis tuæ dilectiónis infúnde; ut in hora éxitus nostri hostem víncere, et ad cœléstem mereámur corónam perveníre."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Joánnis Apóstoli"},{"k":"ref","la":"1 John 3:13-18"},{"k":"text","la":"Caríssimi: Nolíte mirári, si odit vos mundus. Nos scimus, quóniam transláti sumus de morte ad vitam, quóniam dilígimus fratres. Qui non díligit, manet in morte: omnis, qui odit fratrem suum, homicída est. Et scitis, quóniam omnis homicída non habet vitam ætérnam in semetípso manéntem. In hoc cognóvimus caritátem Dei, quóniam ille ánimam suam pro nobis pósuit: et nos debémus pro frátribus ánimas pónere. Qui habúerit substántiam hujus mundi, et víderit fratrem suum necessitátem habére, et cláuserit víscera sua ab eo: quómodo cáritas Dei manet in eo? Filíoli mei, non diligámus verbo neque lingua, sed ópere et veritáte."}],"Graduale":[{"k":"ref","la":"Ps 36:30-31"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium."},{"k":"text","la":"Lex Dei ejus in corde ipsíus: et non supplantabúntur gressus ejus. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 111:1"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Jas 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja."},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus et ornávit eum: stolam glóriæ índuit eum. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 91:13; 91:14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini."},{"k":"ref","la":"Ps 91:3"},{"k":"text","la":"Ad annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem."},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joannes 15:12-16"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Hoc est præcéptum meum, ut diligátis ínvicem, sicut diléxi vos. Majórem hac dilectiónem nemo habet, ut ánimam suam ponat quis pro amícis suis. Vos amíci mei estis, si fecéritis quæ ego præcípio vobis. Jam non dicam vos servos: quia servus nescit, quid fáciat dóminus ejus. Vos autem dixi amícos: quia ómnia, quæcúmque audívi a Patre meo, nota feci vobis. Non vos me elegístis: sed ego elégi vos, et pósui vos, ut eátis, et fructum afferátis: et fructus vester maneat: ut, quodcúmque petiéritis Patrem in nómine meo, det vobis."}],"Offertorium":[{"k":"ref","la":"Ps 20:2-3"},{"k":"text","la":"In virtúte tua, Dómine, lætábitur justus, et super salutáre tuum exsultábit veheménter: desidérium ánimæ ejus tribuísti ei. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Hóstia immaculáta, qua illud Dómini nostri Jesu Christi imménsæ caritátis opus renovámus, sit, Deus Pater omnípotens, sancto Gamíllo intercedénte, contra omnes córporis et animæ infirmitates salutáre remedium, et in extrémo agóne solátium et tutéla."},{"k":"macro","name":"Per eundem"}],"Communio":[{"k":"ref","la":"Matt 25:36; 25:40"},{"k":"text","la":"Infírmus fui, et visitástis me. Amen, amen, dico vobis: Quámdiu fecístis uni ex his frátribus meis minimis, mihi fecístis."}],"Postcommunio":[{"k":"text","la":"Per hæc cœléstia aliménta, quæ, sancti Camílli Confessóris tui sollémnia celebrántes, pia devotióne suscépimus: da, quǽsumus. Dómine; ut, in hora mortis nostræ sacraméntis refécti et culpis ómnibus expiáti, in sinum misericórdiæ tuæ læti súscipi mereámur:"},{"k":"macro","name":"Qui vivis"}]},"hr":{"e46bac31f082e0b2":{"t":"Iv 15, 13, Ps 40, 2\n(Iv 15, 13) Od ove ljubavi nitko veće nema da dade život svoj za prijatelje svoje. (Ps 40, 2) Blago onom koji razumije siromaha i ubogog, u zao dan izbavit će ga Gospodin.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Iv 15, 13) Od ove ljubavi nitko veće nema da dade život svoj za prijatelje svoje.","kn":"(Iv. 15, 13). Od ove ljubavi nitko, nema veće, da dade život svoj za prijatelje svoje. (Ps. 40, 2) Blago onome, koji razumije siromaha d ubogoga, u dan zao izbavit će ga Gospodin. Slava Ocu .. . Od ove ...","knRef":"Kniewald 1942, str. 640–641 (snimka 321) (OCR)"},"fb06bca8bdf005c8":{"t":"<i>Pomolimo se</i>.\nBože, koji si svetog Kamila ukrasio posebnim darom ljubavi da pomaže dušama koje se bore u smrtnoj borbi, ulij nam, molimo, po njegovim zaslugama duh svoje ljubavi da zavrijedimo u času svoje smrti pobijediti neprijatelja i doći do vječne krune.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si sv. Kamila uresio naročitim darom ljubavi, da pomaže dušama, koje se dijele s ovoga svijeta, molimo Te, ulij nam, njegovim zagovorom, duh Tvoje ljubavi, da u času našeg izlaska zaslužimo svladati neprijatelja i dostići nebesku krunu, po G. n.","knRef":"Kniewald 1942, str. 640–641 (snimka 321) (OCR)"},"7564b4e60e745130":{"t":"1 Iv 3, 13-18\nČitanje Poslanice bl. Ivana apostola. Predragi, nemojte se čuditi, ako vas svijet mrzi. Mi znamo da smo iz smrti prešli u život, jer ljubimo braću. Tko ne ljubi, ostaje u smrti. Tko mrzi svojega brata, ubojica je. A znate da nijedan ubojica nema u sebi vječnoga života. Ljubav smo Božju upoznali po tome što je Bog dao svoj život za nas. Tako smo i mi dužni dati svoj život za braću. Ako netko ima dobara ovoga svijeta i vidi svoga brata u nevolji, pa mu zatvori svoje srce, kako da u njemu ostane Božja ljubav? Dječice moja, ne ljubimo riječju i jezikom, nego djelom i istinom.","kn":"Čitanje poslanice bi. Ivana apostola (I, 3, 13-18)^ Predragi! Ne čudite se, ako vas svijet mrzi. Mi znamo, da smo iz smrti preneseni u život, jer ljubimo braću. Tko ne ljubi, ostaje u smrti. Ubojica je, tko mrzi svoga brata. A znate, da nijedan ubojica nema u sebi vječnoga života. U tom smo. upoznali ljubav Božju, što se on žrtvovao za nas. I mi smo dužni žrtvovati se za braću. Tko ima dobra ovoga svijeta i vidi svoga brata u potrebi, te pred njim, zatvori svoj© srce, kako ostaje u njemu ljubav Božja? Sinci moji, ne ljubimo riječju i jezikom, nego djelom i istinom.","knRef":"Kniewald 1942, str. 368–369 (snimka 185) (OCR)"},"6d9e364d27075ba3":{"t":"Ps 36, 30-31\nPravednikova usta raspravljaju o mudrosti i njegov jezik govori o pravdi. Zakon mu je Božji u srcu, i noge mu neće posrnuti.\n\nPs 111, 1\n<i>aleluja</i>, <i>aleluja</i>.\nBlago čovjeku koji se boji Gospodina i koji uživa u njegovim zapovijedima. <i>Aleluja</i>.","kn":"(Ps. 36, 30-31). Pravednikova usta govore mudrost i njegov jezik kazuje pravdu. Zakon je Božji u njegovu srcu i njegove noge ne ce posrnuti.\n\nAleluja, aleluja. (Ps. 111, 1.) Blago čovjeku, koji se boji Go.spodma, .koji žudi zapovijedi njegove, aleluja.","knRef":"Kniewald 1942, str. 540–541 (snimka 271) (OCR)"},"3970c61c60345419":{"t":"Iv 15, 12-16\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme reče Isus svojim učenicima: Ovo je zapovijed moja da se ljubite među sobom kao što sam ja vas ljubio. Nitko nema veće ljubavi od ove da položi život svoj za prijatelje svoje. Vi ste moji prijatelji, ako izvršavate što vam ja zapovijedam. Više vas ne zovem slugama, jer sluga ne zna što radi njegov gospodar; nego vas zovem prijateljima, jer sam vam kazao sve što sam čuo od svoga Oca. Niste vi odabrali mene, nego sam ja odabrao vas i postavio vas da idete i donesete plod i plod vaš da ostane. I što god zapitate od Oca u moje ime dat će vam.","kn":"t Slijedi sv. evanđelje po Ivanu (15, 12-16). U ona vrijeme reče Isus svojim učenicima: Ovo je moja zapovijed, da se ljubite među sobom, kao što sam ja ljubio vas. Nitko nema veće ljubavi O'd ove, da tko svoj Život polaže za svoje prijatelje. Vi ste moji prijatelji, ako vršite, što sam vam zapovjedio. Više vas ne ću zvati slugama, jer sluga ne zna, što radi njegov gospodar. Prozvao sam vas prijateljima, jer sam vam sve objavio, što sam čuo od svoga Oca. Nijeste vi mene izabrali, nego sam ja vas izabrao I odredio vas, da idete i dadete plod i vaš plod da ostane, da vam dadne, štogod zamolite Oca u moje ime.","knRef":"Kniewald 1942, str. 786–787 (snimka 394) (OCR)"},"4e296f3326e0e479":{"t":"Ps 20, 2-3\nU jakosti tvojoj, Gospodine, raduje se pravednik i kliče radi tvoga spasenja, jer si mu ispunio želju srca njegova.","kn":"(Ps. 20, 2-'3). U kreposti Tvojoj Gospodine, raduje se pravednik i kliče nad spasenjem Tvojim, jer si mu ispunio želju duše njegove.","knRef":"Kniewald 1942, str. 818–819 (snimka 410) (OCR)"},"03f2e549a40542cf":{"t":"Bože, Oče svemogući, neka neokaljana žrtva, kojom obnavljamo djelo neizmjerne ljubavi Gospodina našega Isusa Krista, bude po zagovoru svetoga Kamila, spasonosni lijek protiv svih slabosti tijela i duše te utjeha i obrana u smrtnoj borbi.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, Oče svemogući, bila nam zagovorom svetog Kamila ova neokaljana žrtva, kojom ahnavliamo djelo neizmjerne ljubavi Isusa Krista, spasonosni lijek protiv svih slabosti duše i tijela', i utjeha, i obrana u zadnjem bolju, po istom G. n.","knRef":"Kniewald 1942, str. 642–643 (snimka 322) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"0c507a8853da4c59":{"t":"Mt 25, 36 i 40\nBio sam bolestan i posjetili ste me. Zaista, zaista vam kažem: Što god ste učinili jednomu od ove moje najmanje braće, meni ste učinili.","kn":"(Mt. 25, 36). Bolestan sam bio i pohodili ste me. Zaista,, zaista vam kažem: što ste god učinili jednomu od ove najmanje moje braće, meni ste učinili !","knRef":"Kniewald 1942, str. 642–643 (snimka 322) (OCR)"},"4683d396438c05f7":{"t":"<i>Pomolimo se</i>.\nPo ovoj nebeskoj hrani, koju smo s pobožnom odanošću primili slaveći svetkovinu svetoga Kamila priznavaoca tvoga daj, molimo, Gospodine, da zavrijedimo na času naše smrti okrijepljeni sakramentima i očišćeni od svake krivnje biti radosno primljeni u krilo tvoga milosrđa:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
